import json

if 'MATCH:' in search_all_out:
    # Parse the match details
    match_data = {}
    for line in search_all_out.split('\n'):
        line = line.strip()
        if line.startswith('MATCH:'):
            parts = line.split()
            for p in parts:
                if p.startswith('user='):
                    match_data['user_id'] = p.split('user=')[1]
                elif p.startswith('order='):
                    match_data['order_id'] = p.split('order=')[1]
                elif p.startswith('status='):
                    match_data['status'] = p.split('status=')[1]
        elif line.startswith('ITEMS:'):
            match_data['items'] = json.loads(line.split('ITEMS:')[1].strip())
        elif line.startswith('PAYMENT:'):
            match_data['payment_history'] = json.loads(line.split('PAYMENT:')[1].strip())
        elif line.startswith('USER_PAYMENTS:'):
            match_data['user_payments'] = json.loads(line.split('USER_PAYMENTS:')[1].strip())

    print(f"Matched user: {match_data.get('user_id')}")
    print(f"Order: {match_data.get('order_id')}")
    print(f"Status: {match_data.get('status')}")
    print(f"Payment methods: {json.dumps(match_data.get('user_payments', {}), indent=2)}")

    # Get original payment method
    pay_hist = match_data.get('payment_history', [])
    orig_pm = pay_hist[0].get('payment_method_id') if pay_hist and isinstance(pay_hist[0], dict) else None
    print(f"Original payment method: {orig_pm}")
else:
    print("No match found across all users")
    print(search_all_out)
